// A REAL-TOOLING STAND-IN: the `require.extensions` transform hook, which is how essentially
// every legitimate `Module.prototype._compile` caller works — `ts-node`, `tsx`'s CJS half,
// `@babel/register`, `@swc/register`, `pirates` (and therefore `nyc`/`istanbul`),
// `require-in-the-middle` (and therefore `dd-trace` and `elastic-apm-node`),
// `source-map-support`'s install path.
//
// The shape is always the same: replace `require.extensions[ext]`, read the file, transform
// it, then call `module._compile(transformed, filename)` — with the filename of the module
// being loaded, which for an instrumentation tool is ANOTHER package's (or the app's) file.
//
// That is the reason `_compile` cannot simply be denied to dependencies: the dominant
// legitimate use is exactly "a dependency compiling a filename outside its own package". This
// fixture pins that the gate denies it by DEFAULT (it is an identity-granting capability) and
// that the documented escape hatch — a `"compile": true` grant — makes it work again.
const fs = require("node:fs");
const Module = require("node:module");

/** Install the hook. Called by the app, exactly as `require("ts-node/register")` would be. */
function register() {
  // The `.xjs` extension stands in for `.ts`: a source dialect Node cannot load by itself.
  Module._extensions[".xjs"] = function xjsLoader(mod, filename) {
    // Read with `node:fs` on purpose — this fixture runs under capwall, and reading the source
    // it is about to compile is part of the shape real tools have.
    const source = fs.readFileSync(filename, "utf8");
    // The "transform": strip the marker comment. The compiled bytes are NOT the file's bytes,
    // which is why "did the content come from this file?" is not a check capwall can make.
    mod._compile(source.replace(/^\/\/#xjs\n/, ""), filename);
  };
}

module.exports = { register };
